// composables/useJam.ts
import { ref, onMounted, onUnmounted } from 'vue'

export function useJam() {
  const sekarang = ref(new Date())
  let id: ReturnType<typeof setInterval> | undefined
  onMounted(() => {
    id = setInterval(() => (sekarang.value = new Date()), 1000)
  })
  onUnmounted(() => clearInterval(id))    // tanpa ini timer tetap jalan setelah komponen hilang
  return { sekarang }
}

// dipakai di komponen
const { sekarang } = useJam()

// composables/useLocalStorage.ts
import { ref, watch } from 'vue'

export function useLocalStorage(kunci: string, awal: string) {
  const nilai = ref(localStorage.getItem(kunci) ?? awal)
  watch(nilai, (baru) => localStorage.setItem(kunci, baru))
  return nilai
}

