// composables/useOnline.ts
import { ref, onMounted, onUnmounted } from 'vue'

export function useOnline() {
  const online = ref(navigator.onLine)
  const perbarui = () => (online.value = navigator.onLine)
  onMounted(() => {
    window.addEventListener('online', perbarui)
    window.addEventListener('offline', perbarui)
  })
  onUnmounted(() => {
    window.removeEventListener('online', perbarui)
    window.removeEventListener('offline', perbarui)
  })
  return { online }
}

// di komponen: <p v-if="!online">Kamu sedang offline, data disimpan sementara</p>
