// src/stores/pengguna.ts
import { defineStore } from 'pinia'
import { ref, computed } from 'vue'

export const usePengguna = defineStore('pengguna', () => {
  const data = ref<{ nama: string; peran: 'siswa' | 'guru' } | null>(null)
  const masuk = computed(() => data.value !== null)
  const sapaan = computed(() => (data.value ? `Halo, ${data.value.nama}` : 'Halo, tamu'))

  function login(nama: string, peran: 'siswa' | 'guru') { data.value = { nama, peran } }
  function logout() { data.value = null }
  return { data, masuk, sapaan, login, logout }
})

