function buatStoreAbsen() {
  const hadir: string[] = [];
  const jumlahHadir = () => hadir.length;                       // seperti getter
  function absen(nama: string) {                                // seperti action
    if (!hadir.includes(nama)) hadir.push(nama);
  }
  return { hadir, jumlahHadir, absen };
}

